  pub mod s_solver {
    use crate::rt::*;
    pub fn f(self_: &Value, a1: &[&Value]) -> Value {
    let name_0 = cell(&arg(a1, 0)); let f_0 = cell(&arg(a1, 1));
      let pts_0 = cell(&Value::Null); wr(&pts_0, &get(&k!("Shaded"), "points"));
      let lits_0 = cell(&Value::Null); wr(&lits_0, &m_join(&m_map(&rd(&pts_0), args![{ let self_: Value = self_.clone(); cl!(); fnv(move |a3: &[&Value]| -> Value {
        let self_: &Value = &self_;
        let v_2 = cell(&arg(a3, 0));
        return own(&call(&k!("Shaded"), "literal", args![rd(&v_2)]));
        Value::Null
      }) }]), args![sv![", "]]));
      return own(&sv!["const PTS_", &tos(&rd(&name_0)), ": array<f32, ", &tos(&len(&rd(&pts_0))), "> = array<f32, ", &tos(&len(&rd(&pts_0))), ">(", &tos(&rd(&lits_0)), ");\nfn ", &tos(&rd(&name_0)), "() -> f32 {\n  var lo: f32 = 0.0;\n  var hi: f32 = 0.0;\n  var found: bool = false;\n  var px: f32 = PTS_", &tos(&rd(&name_0)), "[0];\n  var pf: f32 = ", &tos(&rd(&f_0)), "(px);\n  for (var j: i32 = 1; j < ", &tos(&len(&rd(&pts_0))), "; j = j + 1) {\n    let cx: f32 = PTS_", &tos(&rd(&name_0)), "[j];\n    let cf: f32 = ", &tos(&rd(&f_0)), "(cx);\n    if (!found && finite(pf) && finite(cf) && pf * cf <= 0.0) { lo = px; hi = cx; found = true; }\n    px = cx;\n    pf = cf;\n  }\n  if (!found) { return 1e30; }\n  var flo: f32 = ", &tos(&rd(&f_0)), "(lo);\n  for (var n: i32 = 0; n < 60; n = n + 1) {\n    let mid: f32 = (lo + hi) / 2.0;\n    let fm: f32 = ", &tos(&rd(&f_0)), "(mid);\n    if (!finite(fm)) { break; }\n    if (flo * fm <= 0.0) { hi = mid; } else { lo = mid; flo = fm; }\n  }\n  return (lo + hi) / 2.0;\n}"]);
      Value::Null
    }
  }
